from functools import lru_cache
from collections import defaultdict


def count_tilings(grid: list[str]) -> int:
    # Validate input.
    if grid == []:
        return 1

    h = len(grid)
    w = len(grid[0])

    for row in grid:
        if len(row) != w:
            raise ValueError("all rows must have the same length")
        for ch in row:
            if ch != "." and ch != "#":
                raise ValueError("only '.' and '#' are allowed")

    # Width 0 has no empty cells.
    if w == 0:
        return 1

    # Orient so that w is the smaller dimension.
    # If rows are longer than columns, transpose the board.
    if h < w:
        # h is already smaller, keep it.
        pass
    else:
        # Transpose: new_h = w, new_w = h.
        new_grid = []
        for c in range(w):
            new_grid.append("".join(grid[r][c] for r in range(h)))
        grid = new_grid
        h, w = w, h

    # Bits 0..w-1: empty cells ('.') in each row.
    allowed = []
    for row in grid:
        mask = 0
        bit = 1
        for ch in row:
            if ch == ".":
                mask |= bit
            bit <<= 1
        allowed.append(mask)

    full = (1 << w) - 1

    # Transfer for a pair of adjacent rows:
    # incoming mask: cells in the upper row already covered from above.
    # outgoing mask: cells in the lower row covered by tiles placed in the upper row.
    #
    # Return a dict:
    #   outgoing_mask -> number of ways, for a fixed incoming mask.
    #
    # Tiles are placed by scanning uncovered cells in the upper row from left to right.
    # A placement that first covers column c is enumerated from c:
    #   - horizontal domino (upper row c, c+1)
    #   - vertical domino (upper c, lower c)
    #   - L tromino in 2x2 box with top-left c, missing:
    #       top-right, bottom-left, bottom-right
    #   - L tromino in 2x2 box with top-left c-1, missing top-left
    #     (covers upper c, lower c-1, lower c)
    #
    # The last option is necessary because an L tromino may cover a cell in the
    # upper row at column c while its bounding 2x2 box starts at column c-1.

    @lru_cache(maxsize=None)
    def dfs(cur: int, nxt: int, ac: int, an: int):
        # cur: already covered cells in upper row
        # nxt: already covered cells in lower row by tiles started in upper row
        # ac/ac2 masks indicate legal upper/lower cells.
        # If current upper cell is '#', cur must not contain it; this is enforced by
        # only placing tiles on allowed bits.

        # A safe incoming mask is guaranteed by callers.
        if (cur | nxt) & ~(ac | an) == 0:
            target = ac & ~cur
            if target == 0:
                # All legal cells in the upper row are covered.
                return {nxt: 1}

            bit = target & -target
            c = bit.bit_length() - 1
            nxt_bit = 1 << c

            res = {}

            def add(ncur: int, nnxt: int):
                res[nnxt] = res.get(nnxt, 0) + 1

            # 1. Horizontal domino in upper row: (c, c+1)
            if c + 1 < w:
                nb = bit << 1
                if (ac & nb) and not (cur & nb):
                    add(cur | bit | nb, nxt)

            # 2. Vertical domino: (upper c, lower c)
            if (an & nxt_bit) and not (nxt & nxt_bit):
                add(cur | bit, nxt | nxt_bit)

            if c + 1 < w:
                nb = bit << 1
                nb_next = nb

                # 3. L tromino, top-left c, missing top-right:
                #    covers upper c, lower c, lower c+1
                if (an & nxt_bit) and (an & nb_next) and not (nxt & (nxt_bit | nb_next)):
                    add(cur | bit, nxt | nxt_bit | nb_next)

                # 4. L tromino, top-left c, missing bottom-left:
                #    covers upper c, upper c+1, lower c+1
                if (ac & nb) and not (cur & nb) and (an & nb_next) and not (nxt & nb_next):
                    add(cur | bit | nb, nxt | nb_next)

                # 5. L tromino, top-left c, missing bottom-right:
                #    covers upper c, upper c+1, lower c
                if (ac & nb) and not (cur & nb) and (an & nxt_bit) and not (nxt & nxt_bit):
                    add(cur | bit | nb, nxt | nxt_bit)

            # 6. L tromino, top-left c-1, missing top-left:
            #    covers upper c, lower c-1, lower c
            if c > 0:
                prev = 1 << (c - 1)
                if (an & prev) and (an & nxt_bit) and not (nxt & (prev | nxt_bit)):
                    add(cur | bit, nxt | prev | nxt_bit)

            return res
        else:
            # Invalid state: a tile has touched a '#' cell.
            return {}

    @lru_cache(maxsize=None)
    def transfer(incoming: int, ac: int, an: int):
        if incoming & ~ac:
            return ()
        d = dfs(incoming, 0, ac, an)
        if not d:
            return ()
        return tuple(d.items())

    dp = {0: 1}

    for r in range(h):
        ac = allowed[r]
        an = allowed[r + 1] if r + 1 < h else 0
        ndp = defaultdict(int)

        for incoming, cnt in dp.items():
            trans = transfer(incoming, ac, an)
            for outgoing, ways in trans:
                ndp[outgoing] += cnt * ways

        dp = dict(ndp)

    # After the last row, no tile may extend past the board.
    return int(dp.get(0, 0))
